  TILE_ART['tg2-' + id] = 'tile-tg2-' + id;
  TILE_ART['tc-' + id] = 'tile-tc-' + id;
  TILE_ART['td-' + id] = 'tile-td-' + id;
  TILE_ART['tr-' + id] = 'tile-tr-' + id;
  TILE_ART['tl-' + id] = 'tile-tl-' + id;
